WITH promo_sales AS (SELECT p.p_promo_sk, p.p_promo_id, p.p_promo_name, COALESCE(cs.cs_ext_discount_amt,0) AS cs_discount, COALESCE(cs.cs_ext_sales_price,0) AS cs_sales, COALESCE(ss.ss_ext_discount_amt,0) AS ss_discount, COALESCE(ss.ss_ext_sales_price,0) AS ss_sales, COALESCE(st.store_cnt,0) AS store_cnt FROM promotion p LEFT JOIN (SELECT cs_promo_sk, SUM(cs_ext_discount_amt) AS cs_ext_discount_amt, SUM(cs_ext_sales_price) AS cs_ext_sales_price FROM catalog_sales GROUP BY cs_promo_sk) cs ON p.p_promo_sk = cs.cs_promo_sk LEFT JOIN (SELECT ss_promo_sk, SUM(ss_ext_discount_amt) AS ss_ext_discount_amt, SUM(ss_ext_sales_price) AS ss_ext_sales_price FROM store_sales GROUP BY ss_promo_sk) ss ON p.p_promo_sk = ss.ss_promo_sk LEFT JOIN (SELECT ss_promo_sk, COUNT(DISTINCT ss_store_sk) AS store_cnt FROM store_sales GROUP BY ss_promo_sk) st ON p.p_promo_sk = st.ss_promo_sk) SELECT p_promo_id, p_promo_name, (cs_discount + ss_discount) AS total_discount_amount, (cs_sales + ss_sales) AS total_sales_amount, CASE WHEN (cs_sales + ss_sales) = 0 THEN 0 ELSE (cs_discount + ss_discount) / (cs_sales + ss_sales) END AS discount_ratio, CASE WHEN (cs_discount + ss_discount) / NULLIF((cs_sales + ss_sales),0) > 0.2 THEN 'HIGH_DISCOUNT' WHEN (cs_discount + ss_discount) / NULLIF((cs_sales + ss_sales),0) BETWEEN 0.1 AND 0.2 THEN 'MEDIUM_DISCOUNT' ELSE 'LOW_DISCOUNT' END AS discount_category, DENSE_RANK() OVER (ORDER BY CASE WHEN (cs_sales + ss_sales) = 0 THEN 0 ELSE (cs_discount + ss_discount) / (cs_sales + ss_sales) END DESC) AS discount_ratio_rank, store_cnt FROM promo_sales ORDER BY discount_ratio_rank LIMIT 30
